const row = $json;
const id = String(row.ID || '').trim();
const inputText = String(row.Input_Text || '');
const metaRaw = row.Input_Metadata_JSON;

// Parse the existing event from metadata JSON
// Format: {"existing": ["Event Name", "HH:MM", "HH:MM"], ...}
let existing = null;
try {
  const meta = (typeof metaRaw === 'string') ? JSON.parse(metaRaw) : metaRaw;
  existing = meta && meta.existing;
} catch (e) {
  throw new Error('Could not parse Input_Metadata_JSON for ' + id + ': ' + e.message);
}
if (!Array.isArray(existing) || existing.length < 3) {
  throw new Error('existing[] missing or malformed for ' + id);
}

const eventName = String(existing[0]);
const startTime = String(existing[1]); // HH:MM
const endTime = String(existing[2]);   // HH:MM

// Extract the weekday from input text ("on Wednesday")
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let weekday = null;
for (const wd of weekdays) {
  const re = new RegExp('\\b' + wd + '\\b');
  if (re.test(inputText)) { weekday = wd; break; }
}
if (!weekday) {
  throw new Error('No weekday found in Input_Text for ' + id);
}

// Compute next occurrence (today excluded — matches Cat3 runner logic)
const today = new Date();
const targetIdx = weekdays.indexOf(weekday);
const todayIdx = today.getDay();
let daysUntil = (targetIdx - todayIdx + 7) % 7;
if (daysUntil === 0) daysUntil = 7;
const eventDate = new Date(today);
eventDate.setDate(eventDate.getDate() + daysUntil);
const yyyy = eventDate.getFullYear();
const mm = String(eventDate.getMonth() + 1).padStart(2, '0');
const dd = String(eventDate.getDate()).padStart(2, '0');
const dateStr = yyyy + '-' + mm + '-' + dd;

// Build ISO datetimes with Europe/Sarajevo offset (CEST = +02:00 in May 2026)
const startISO = dateStr + 'T' + startTime + ':00+02:00';
const endISO   = dateStr + 'T' + endTime   + ':00+02:00';

return {
  json: {
    test_id: id,
    event_summary: eventName,
    description: 'Pre-populated for ' + id + ' (existing_event_conflict). Auto-created by EXC Pre-Populator.',
    start_iso: startISO,
    end_iso: endISO,
    weekday: weekday,
    date_str: dateStr
  }
};
